from functools import wraps

def rate_limit(leak_rate, capacity, clock):
    water = 0.0
    last_leak = None

    def decorator(func):
        @wraps(func)
        def wrapped(*args, **kwargs):
            nonlocal water, last_leak

            now = clock()
            if last_leak is not None:
                water = max(0.0, water - (now - last_leak) * leak_rate)
            last_leak = now

            if water + 1 <= capacity:
                water += 1
                return func(*args, **kwargs)
            return False

        return wrapped

    return decorator

